def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = next(v for v in Counter(v for row in grid for v in row) if v != background)
    out = [row[:] for row in grid]

    # Connect marker cells along each row and column.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for c in range(min(cols, default=0), max(cols, default=-1) + 1):
            if cols and grid[r][c] == background:
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for r in range(min(rows, default=0), max(rows, default=-1) + 1):
            if rows and grid[r][c] == background:
                out[r][c] = 3
    return out
